export function createFilter(host) {
  host.onFrame(({ ctx, width, height, faces, time }) => {
    const face = faces?.[0];
    const p = face?.landmarks;
    if (!p?.forehead || !p.leftEye || !p.rightEye) return;

    const eyeSpan = Math.hypot(
      (p.rightEye.x - p.leftEye.x) * width,
      (p.rightEye.y - p.leftEye.y) * height
    );
    if (eyeSpan < 1) return;

    const smile = Math.max(0, Math.min(1, face.expressions?.smile ?? 0));
    ctx.save();
    ctx.translate(p.forehead.x * width, p.forehead.y * height);
    ctx.scale(eyeSpan, eyeSpan);

    ctx.beginPath();
    ctx.moveTo(-1.25, 0.24);
    ctx.quadraticCurveTo(0, -0.28, 1.25, 0.24);
    ctx.strokeStyle = `rgba(130, 240, 255, ${0.65 + smile * 0.3})`;
    ctx.lineWidth = 0.09;
    ctx.shadowColor = '#8af3ff';
    ctx.shadowBlur = 0.12 + smile * 0.24;
    ctx.stroke();
    ctx.shadowBlur = 0;

    for (let i = 0; i < 5; i++) {
      const angle = time * 0.7 + i * (Math.PI * 2 / 5);
      const x = Math.cos(angle) * (0.78 + (i % 2) * 0.38);
      const y = -0.18 + Math.sin(angle) * 0.3;
      const r = 0.045 + smile * 0.018;
      ctx.beginPath();
      for (let k = 0; k < 8; k++) {
        const a = -Math.PI / 2 + k * Math.PI / 4;
        const radius = k % 2 === 0 ? r : r * 0.38;
        const px = x + Math.cos(a) * radius;
        const py = y + Math.sin(a) * radius;
        if (k === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fillStyle = '#fff4b8';
      ctx.fill();
    }

    ctx.restore();
  });
}
